-- Japan pilot round 2, chat 1 (institutions), 2026-10-20.
-- Source: docs/research/japan_pilot/results_2026-10-20_round2/. 20 new places + 7 backfills (existing rows only get missing link fields filled). No deletes.
BEGIN;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('tyo-terpsichore', 'Terpsichore', 'テルプシコール（中野テルプシコール）', 'theatre_small', 'tokyo', 'active', 1, ARRAY['dance','performance']::TEXT[], 'Terpsichore is a small studio-theatre beside the tracks south of Nakano Station. It opened in 1981 and was named by the dance critic Masaru Ichikawa after the Greek muse of dance. It works as both a rehearsal room and a performance space, and its calendar is dominated by butoh and experimental dance put on by independent artists who rent the room.

Since 1985 it has run the Butoh Newcomers Series each spring, whenever at least two applicants come forward. Autumn 2026 includes a solo by Gaspar Lizano (30 Oct), a Hijikata memorial programme by Hokutoza (14–15 Nov, pay what you can), a three-day butoh workshop with Saga Kobayashi (21–23 Nov, already full) and Invisible forest Vol.3 (28–29 Nov).

Each show is booked directly with its organiser through the contact listed on the schedule page. To apply for the newcomers series or to rent the studio, use the venue''s inquiry page.', 'Nakano', '3-49-15-1F Nakano, Nakano-ku, Tokyo 164-0001', 'https://www.studioterpsichore.com/', NULL, 'https://www.studioterpsichore.com/day.html', ARRAY['butoh','experimental_dance','workshops','studio_theatre','rental']::TEXT[], 5, 'yes', 'Japanese-only site; book with each show''s organiser; workshops are listed here and can fill up', 'html_calendar', false, 'https://www.studioterpsichore.com/', '2026-10-20', 'Tokyo''s core small butoh room. In the window: Lizano solo (30 Oct) and the Hokutoza Hijikata memorial (14–15 Nov, donation-based).', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('tyo-polaris', 'POLARIS tokyo', NULL, 'venue_music', 'tokyo', 'active', 2, ARRAY['music','sound']::TEXT[], 'POLARIS is a live space in Minami-Aoyama run by Niji no Hoshi Co. It describes itself as a floor-level room with a 3.7 m ceiling. It programmes small-format concerts almost every night, leaning towards improvisation and instrumental experiment, and often pairs jazz, rock and electronic players in unusual combinations.

The late-October 2026 calendar includes Andrea Centazzo with Otomo Yoshihide (22 Oct), a violin, bass and drums trio led by Katsui Yuji (26 Oct), and pianist Suga Dairo with cellist Nakagawa Yuki (27 Oct). In September 2023 it hosted all seven nights of MIMINOIMI''s ambient week.

Doors usually open at 19:00 and shows start at 19:30. Check each event page for tickets. The venue also offers memberships, lunch service and room rental.', 'Minami-Aoyama', NULL, 'https://polaristokyo.com/', 'https://www.instagram.com/polaris_tokyo/', 'https://polaristokyo.com/schedule', ARRAY['improv','experimental','jazz','ambient','small_room']::TEXT[], 4, 'yes', 'Japanese-only schedule but lineups are readable', 'html_calendar', true, 'https://polaristokyo.com/schedule', '2026-10-20', 'Otomo Yoshihide duo on 22 Oct. Address unconfirmed: site metadata says Minami-Aoyama but a 2023 listing said Kanda. Check the access page before sending anyone.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('tyo-blackbird', 'Black Bird Eatery', 'ブラック・バード・イータリー', 'shop_venue', 'tokyo', 'active', 2, ARRAY['music','sound','performance']::TEXT[], 'Black Bird Eatery is a small queer-run eatery, bar and event room four minutes from Sasazuka Station on the Keio line, one stop from Shinjuku. It describes itself as an inclusive space centred on LGBTQIA+ people, especially non-binary people, with a zero-tolerance harassment policy and no smoking inside or out.

Besides food and drink it runs its own series (a dance night called EVERYBODY DANCE (or not), workshops and an open mic) and rents the room to outside organisers. The ambient collective MIMINOIMI holds its Food For Ears concerts here; vol.12 on 7 Nov 2026 features Nick Tsai with Tomotsugu Nakamura, Moskitoo and harpist Yoriko Shirai.

Check the event calendar on the website. Contact goes through the site''s contact page, Instagram or Facebook.', 'Sasazuka', '2-13-13 Sasazuka, Shibuya-ku, Tokyo', 'https://www.blackbirdtokyo.com/', 'https://www.instagram.com/black_bird_tokyo', 'https://www.blackbirdtokyo.com/event-calendar.html', ARRAY['ambient','experimental','queer_space','open_mic','workshops','dance_night']::TEXT[], 4, 'yes', 'Bilingual site; strictly non-smoking', 'html_calendar', false, 'https://www.miminoimi.me/', '2026-10-20', 'MIMINOIMI Food For Ears vol.12 on 7 Nov (adv 3500 / door 4000). Lat/lng from the venue''s own map embed.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('tyo-stspot', 'ST Spot', 'STスポット', 'theatre_small', 'tokyo', 'active', 1, ARRAY['dance','theatre','performance','music']::TEXT[], 'ST Spot is a basement black box near Yokohama Station. The city opened it in 1987, and since 2004 it has been run by the NPO ST Spot Yokohama, which grew out of a volunteer citizens'' committee. It bills itself as a space for every kind of artist and has long been an early stage for young contemporary dance, theatre, music and video makers.

Its best-known strand is Lab 20, a showcase for new contemporary dance artists. Participants for Lab 20#25 have been announced, and a Lab20+Wave event runs on 25 Oct 2026. This autumn the venue also co-hosts a tribute to choreographer Mika Kurosawa ten years after her death, with workshops on 31 Oct and 20 Nov.

The theatre publishes a web magazine of reviews (ST通信) and has a mailing list and an English page. Tickets are booked through its own reservation page.', 'Yokohama Station west (Kitasaiwai)', 'Yokohama ST Bldg B1, 1-11-15 Kitasaiwai, Nishi-ku, Yokohama 220-0004', 'https://stspot.jp/', 'https://www.instagram.com/stspot_theater/', 'https://stspot.jp/schedule/', ARRAY['contemporary_dance','showcase','lab20','emerging_choreographers','black_box']::TEXT[], 4, 'yes', 'English page exists; programme pages are in Japanese', 'html_calendar', false, 'https://stspot.jp', '2026-10-20', 'Day trip – Yokohama: about 30 min from Shibuya. Lab20+Wave on 25 Oct; Kurosawa tribute workshops on 31 Oct and 20 Nov.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('tyo-wwwbeta', 'WWWβ (WWW Beta)', 'WWWβ', 'club', 'tokyo', 'active', 2, ARRAY['music']::TEXT[], 'WWWβ is the basement club room beneath the WWW and WWW X live houses on Spain-zaka in Shibuya. It was relaunched under this name in August 2017 with a Funktion-One sound system, and since then it has been one of the rooms where Tokyo''s younger electronic underground holds all-nighters: deconstructed club, hard dance and trance crews.

Collectives book the room for their own parties. For example, the XPEED crew took over WWW and WWWβ on 20 June 2026 for a 23:30–05:00 night. Events are 20+ with photo ID.

Tickets usually go through Resident Advisor or LivePocket. Follow the WWWShibuya promoter page on RA for upcoming club nights.', 'Shibuya (Udagawacho)', 'Rise Bldg B1F, 13-17 Udagawacho, Shibuya-ku, Tokyo 150-0042', 'https://www-shibuya.jp', NULL, NULL, ARRAY['club','experimental_electronic','collectives','all_night','trance','deconstructed_club']::TEXT[], 4, 'yes', '20+ only, photo ID required', 'ra', true, 'https://de.ra.co/events/2451676', '2026-10-20', 'Fills the club gap. No in-window night found yet; check RA weekly.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('kyo-galerie16', 'galerie 16', 'ギャラリー16', 'gallery', 'kyoto', 'active', 2, ARRAY['visual_art','painting']::TEXT[], 'galerie 16 is a long-running independent contemporary gallery on the third floor of the Togawa Building on Sanjo-dori, just north of Shirakawa bridge in Higashiyama. It runs short shows, usually about two weeks each, of painting, installation and conceptual work.

Current programming is Masato Ikebe''s ''Part and Infinity'' (13–25 Oct 2026), followed by another show from 31 Oct to 8 Nov. Earlier in 2026 it showed a two-person installation by Keiko Kurachi and Satoru Takahashi and a solo by Rui Sakurai. A 2024 show turned the gallery into a mock job-hunting seminar, which shows how open it is to unconventional formats.

Open 12:00–18:00 (17:00 on the last day), closed Mondays. The English page and contact form are the routes in.', 'Higashiyama / Sanjo-Shirakawa', 'Togawa Bldg 3F, 394 Sekisen''in-cho, Sanjo-dori Shirakawabashi-agaru, Higashiyama-ku, Kyoto 605-0021', 'https://art16.net/', 'https://instagram.com/galerie16.kyoto', 'https://art16.net/exhibitions/', ARRAY['independent_gallery','emerging','installation']::TEXT[], 4, 'yes', 'Free; small third-floor room', 'html_calendar', false, 'https://art16.net/exhibitions/', '2026-10-20', 'Easy walk from the Sanjo/Higashiyama galleries. The next show opens 31 Oct; openings are the time to meet people.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('kyo-monade', 'monade contemporary', '単子現代', 'gallery', 'kyoto', 'active', 2, ARRAY['visual_art','performance']::TEXT[], 'monade contemporary is a small basement gallery and event space in the Yasaka Building in Tsukimi-cho, on the southern edge of Gion. F. Atsumi of Art-Phil, an editor and critic, opened it in July 2022 as a place to think about art, philosophy and society together. It combines exhibitions with talks and events, and a small cafe operates during shows.

It shows Japanese artists living abroad, visiting international artists and local artists. Coming up is hiRatanaO''s three-day participatory piece ''Jitsumen'' (28–30 Oct 2026), with evening opening and closing receptions.

The site lists an open call, a rental option and an artist-in-residence strand called AIR nomade, which makes it one of the more approachable Kyoto spaces for a visiting artist who wants to show work or meet people. Use the contact page.', 'Gion south / Higashiyama', 'Room 2, B1F Yasaka Bldg, 10-2 Tsukimi-cho, Higashiyama-ku, Kyoto 605-0829', 'https://monadecontemporary.art-phil.com/', 'https://www.instagram.com/monadecontemporary', 'https://monadecontemporary.art-phil.com/?page_id=20', ARRAY['project_space','open_call','residency','talks','cafe']::TEXT[], 4, 'yes', 'Event texts are often bilingual; open only on show days', 'html_calendar', false, 'https://monadecontemporary.art-phil.com/?p=1714', '2026-10-20', 'Receptions on 28 and 30 Oct (19:00–21:00). Good fit for the client''s ''places to show work'' goal.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('kyo-delta', 'DELTA | KYOTOGRAPHIE Permanent Space', 'DELTA', 'gallery', 'kyoto', 'active', 3, ARRAY['photography','visual_art']::TEXT[], 'DELTA is KYOTOGRAPHIE''s year-round base in the Demachi Masugata shopping arcade. It combines a small photography gallery, a bistro and guest rooms. Between festival editions it keeps the KYOTOGRAPHIE network active; the festival describes it as a home for its academy and its support for new artists, with a residency that links art and craft.

In autumn 2026 the gallery showed Akihito Yoshida''s ''Theme—Tango'' into mid-October.

For anyone who wants to connect with the photo-festival crowd outside April and May, it is the practical place to go. Open Wed, Thu and Sun 11:00–18:00, Fri–Sat until 21:00, closed Mon–Tue. Check Instagram for changes.', 'Demachi / Masugata', '62 Sanei-cho, Kamigyo-ku, Kyoto 602-0826', 'https://delta.kyotographie.jp/', 'https://www.instagram.com/delta.kyotographie/', 'https://delta.kyotographie.jp/#schedule_area', ARRAY['photography','festival_base','residency','cafe']::TEXT[], 3, 'yes', 'English pages available', 'html_calendar', false, 'https://delta.kyotographie.jp/', '2026-10-20', 'Secondary pick: drop in for the bistro and ask about KG+ open calls for 2027.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('kyo-galleryparc', 'Gallery PARC (GRAND MARBLE)', 'ギャラリー・パルク', 'gallery', 'kyoto', 'dormant', 3, ARRAY['visual_art','photography','performance']::TEXT[], 'Gallery PARC was founded in July 2010 by the Kyoto bakery company Grand Marble as a gallery for young makers in art, craft, design, photography, video and performance. Across three locations it staged more than 220 exhibitions and ran an open-call art competition.

In a notice dated 8 Aug 2026 the gallery says it stopped holding exhibitions in January 2025. It continues without a fixed venue: directing exhibitions for companies and organisations, handling installation and coordination for artists, editing artist books and selling work online through parcstore. It says it hopes to reopen when conditions allow.

Don''t send anyone here expecting a show. Artists can still contact the office through its About/Contact page about installation or publishing support.', 'Horikawa-Nakadachiuri', 'Horikawa Shin-Bunka Bldg 2F, 287 Saikachi-cho, Kamigyo-ku, Kyoto 602-8242', 'https://galleryparc.com/', 'http://instagram.com/galleryparc/', 'https://galleryparc.com/pages/exhibition.html', ARRAY['independent_gallery','young_makers','curatorial_office']::TEXT[], 4, 'unknown', NULL, 'manual', false, 'https://galleryparc.com/pages/news/2026/2026_0808_galleryparc.html', '2026-10-20', 'DORMANT as a venue. Kept so nobody is sent to an empty room.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('kyo-soto', 'Soto', '外 soto', 'live_house', 'kyoto', 'active', 1, ARRAY['music','sound','performance']::TEXT[], 'Soto is a studio and live house in Shishigatani, north-east Kyoto, run by the three-piece band Kukangendai. The band moved from Tokyo to Kyoto in September 2016 and converted a former roadside rest stop beside the Kinrin-shako-mae bus stop into its base. By day it is the band''s rehearsal and recording studio; at night it hosts concerts that Soto or Kukangendai direct or co-produce, rather than open rentals.

The programme ranges across experimental rock, electronics, noise, improvisation and sound art, with visiting international acts. The 2026 tenth-anniversary season included a collaboration between Kukangendai and the Kyoto theatre company Chiten. Coming up: an industrial woodblock-printing performance by Vivian sui method (31 Oct), NRQ (7 Nov) and BIG|BRAVE with SALLT (19 Nov).

Tickets are usually ¥2,500 reserved / ¥3,000 at the door. Reserve through each event page; there is also an English page and a newsletter.', 'Shishigatani / Kinrin-shako-mae (Sakyo)', '18 Shishigatani Honen-in Nishimachi, Sakyo-ku, Kyoto 606-8427', 'https://soto-kyoto.jp/', 'https://www.instagram.com/soto_kyoto/', 'https://soto-kyoto.jp/schedule/', ARRAY['experimental','noise','improv','electronic','band_run','international']::TEXT[], 5, 'yes', 'English page; about 20 min by city bus from central Kyoto (Kinrin-shako-mae stop)', 'html_calendar', false, 'https://soto-kyoto.jp/schedule/', '2026-10-21', 'With UrBANGUILD, one of the two essential Kyoto music rooms for this client. In the window: Vivian sui method (31 Oct), NRQ (7 Nov).', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('kyo-underthrow', 'UNDER-THROW (Chiten)', '地点 / アンダースロー', 'theatre_small', 'kyoto', 'active', 2, ARRAY['theatre','performance','music']::TEXT[], 'UNDER-THROW is the atelier theatre of Chiten, a Kyoto company led by director Motoi Miura that builds productions from collaged fragments of existing texts and is known for a stylised, almost musical way of speaking. Chiten moved from Tokyo to Kyoto in 2005, and in 2013 converted a derelict former music venue into this studio, which seats around 40 and keeps the company''s repertoire in rotation alongside new work.

In 2022 the company opened a diner, TUPPERWAY, next door so that audiences can eat and talk before and after shows. Recent runs at UNDER-THROW include Fatzer (May 2026) and The Master and Margarita (July 2026). Chiten often works with the band Kukangendai, which links it to the Soto live house.

The website has an English section, a schedule, ticketing and a ''For Youth'' page aimed at first-time audiences. Join the mailing list to catch the next run.', 'Sakyo (Jodoji area)', NULL, 'https://chiten.org/en/', 'https://www.instagram.com/chitenkyoto/', 'https://chiten.org/en/schedule/', ARRAY['experimental_theatre','company_atelier','repertory','kukangendai']::TEXT[], 5, 'yes', 'Text-heavy Japanese-language theatre; check each run for surtitles', 'html_calendar', true, 'https://ja.kyoto.travel/times/night/event/?p=2', '2026-10-21', 'Secondary discipline (theatre), but tied to Kyoto''s experimental music scene through Kukangendai. No run found inside the window; address not confirmed on an official page.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('kyo-terras', 'Kyoto Seika University Gallery Terra-S', '京都精華大学ギャラリーTerra-S', 'gallery', 'kyoto', 'active', 3, ARRAY['visual_art']::TEXT[], 'Terra-S is the university gallery of Kyoto Seika University, on the third floor of the Meisokan building on the Iwakura campus in the north of the city, a one-minute walk from Kyoto Seika-mae station on the Eizan line. It runs curated exhibitions and shows proposed by students, alumni and staff, and it is open to the public free of charge.

The 2026 programme has included a materials-recycling project by the collective Fukusanbutsu Santen (副産物産店) with a public talk, a cross-faculty student group show, a textile-dyeing show by alumni, and graduate research presentations. A show listed from 2 Oct to 9 Nov 2026 is running now.

It is the place to see what Kyoto''s next generation of artists, designers and manga makers are doing. Open 11:00–18:00, generally closed Sundays; check the gallery site for each show.', 'Iwakura (Sakyo)', 'Meisokan 3F, Kyoto Seika University, 137 Iwakura Kino-cho, Sakyo-ku, Kyoto 606-8588', 'https://gallery.kyoto-seika.ac.jp/', NULL, 'https://gallery.kyoto-seika.ac.jp/', ARRAY['university_gallery','emerging','student_shows']::TEXT[], 3, 'yes', 'Free; on campus', 'html_calendar', false, 'https://artscape.jp/exhibition/pickup/10166975_1997.html', '2026-10-21', 'Niche: worth it only if the client is up north (Eizan line). Current show runs to 9 Nov.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('tyo-karas', 'KARAS APPARATUS', 'カラス アパラタス', 'dance_studio', 'tokyo', 'active', 1, ARRAY['dance']::TEXT[], 'KARAS APPARATUS is the creation space of choreographer Saburo Teshigawara and his company KARAS, opened in July 2013 in a three-floor building off the Suzuran-dori shopping street, three minutes from Ogikubo Station''s west exit. It contains a small hall, a rehearsal studio and a gallery, and every floor is covered in dance mat.

Its core programme is the Update Dance series: new or reworked pieces by Teshigawara and Rihoko Sato, shown at close range for modest prices and changing roughly monthly; more than a hundred have been made here. No.122, ''Ophelia'', ran 3–13 Oct 2026 (¥5,000 reserved, students ¥3,000).

KARAS dancers teach weekly classes in the Teshigawara method, open to all ages and levels. A one-off trial class costs ¥2,000 and is booked by email; class information is published in English as well as Japanese.', 'Ogikubo', '1F/B1/B2, 5-11-15 Ogikubo, Suginami-ku, Tokyo 167-0051', 'https://www.st-karas.com/', 'https://www.instagram.com/saburoteshigawara.karas/', 'https://www.st-karas.com/karas_apparatus', ARRAY['contemporary','company_studio','open_class','work_in_progress','update_dance']::TEXT[], 4, 'yes', 'Workshop info in English; trial class ¥2,000 booked by email; performances are non-verbal', 'html_calendar', false, 'https://www.st-karas.com/karas_apparatus', '2026-10-21', 'The most direct ''take class'' door in Tokyo for this client. Email for a trial class; watch for the next Update Dance.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('tyo-ypam', 'YPAM (Yokohama International Performing Arts Meeting)', '横浜国際舞台芸術ミーティング', 'festival', 'tokyo', 'active', 2, ARRAY['theatre','dance','performance','music']::TEXT[], 'YPAM is Japan''s longest-running platform for contemporary performing-arts professionals. It began in 1995 in Tokyo as the Tokyo Performing Arts Market, moved to Yokohama in 2011 and took its current name in 2021. It is organised by Yokohama and Kanagawa arts bodies together with the Japan Center, Pacific Basin Arts Communication.

Each edition combines a curated programme and showcase, meetings and pitching sessions for presenters, and YPAM Fringe, an open-call, non-curated festival in which companies register their own shows at venues in Kanagawa. Most performances are open to the public. YPAM2025 ran 28 Nov–14 Dec 2025; the next edition, YPAM2027, moves to 5–14 Feb 2027.

For an artist, it is the most efficient single gathering for meeting Asian and international presenters. Registration for YPAM Fringe 2027 closed on 30 Sep 2026; watch the site for professional registration.', 'Yokohama (citywide)', NULL, 'https://ypam.jp/2025/index.en.html', NULL, 'https://ypam.jp/2025/program/index.en.html', ARRAY['international','platform','fringe','presenters','networking']::TEXT[], 3, 'yes', 'Fully bilingual; international professionals attend', 'html_calendar', false, 'https://ypam.jp/2025/news/newsroom/detail_1775011356.en.html', '2026-10-21', 'Day trip – Yokohama: not in the window (next edition 5–14 Feb 2027). Festival calendar only. Director Hiromi Maruoka stepped down 31 Mar 2026; run collectively by the existing team.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('tyo-pitinn', 'Shinjuku PIT INN', '新宿ピットイン', 'venue_music', 'tokyo', 'active', 2, ARRAY['music']::TEXT[], 'Shinjuku PIT INN is a basement jazz club in Shinjuku 3-chome, founded in 1965, which marked its 60th anniversary in 2025. It runs up to three slots a day: a cheap morning set, an afternoon session and an evening show, and it streams many evening sets through its own subscription service.

The programming stretches from mainstream jazz to the free and improvised end of the Japanese scene. Late October 2026 includes Shun Ishiwaka''s three-day, six-show run (23–25 Oct), saxophonist Eiichi Hayashi''s monthly residency (26 Oct) and guitarist Tokutaro Hosoi''s A.N.D (27 Oct). Visiting international groups appear regularly.

Evening shows open at 19:00 and start at 19:30, from ¥3,300 including one drink. Reserve through the form on each show''s page for priority entry; morning and afternoon sets need no booking.', 'Shinjuku 3-chome', 'Accord Shinjuku B1, 2-12-4 Shinjuku, Shinjuku-ku, Tokyo 160-0022', 'https://pit-inn.com/', 'https://www.instagram.com/pitinn_shinjuku/', 'https://pit-inn.com/schedule', ARRAY['jazz','free_jazz','improv','daily_shows','streaming']::TEXT[], 4, 'yes', 'English page; morning (¥1,430) and afternoon (¥2,200) sets are cheap walk-ins', 'html_calendar', false, 'https://pit-inn.com/', '2026-10-21', 'Pick the free/improv nights (Hayashi, Hosoi) rather than straight-ahead jazz. Afternoon sets are where young players are heard.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('tyo-tokas', 'Tokyo Arts and Space Hongo (TOKAS)', 'トーキョーアーツアンドスペース本郷', 'art_centre', 'tokyo', 'active', 2, ARRAY['visual_art','performance','sound']::TEXT[], 'Tokyo Arts and Space (TOKAS) is a public art centre for emerging and experimental art, run under the Museum of Contemporary Art Tokyo by the Tokyo Metropolitan Foundation for History and Culture. Its Hongo building, between Ochanomizu and Suidobashi, presents free exhibitions, and its Creator-in-Residence programme (since 2006) hosts Japanese and international artists and holds open studios.

Its strands include TOKAS-Emerging (solo shows for artists 35 and under living in Japan, chosen by open call; 186 applications in 2026), ACT for artists who have been through TOKAS, and the international TOKAS Project. TOKAS Project Vol. 9, marking 20 years of exchange with Seoul, runs 3 Oct–8 Nov 2026, with a free theatre performance by Arata Mino on 7 Nov (booking required).

Open 11:00–19:00, closed Mondays, free. For a visiting artist, the residency open calls and open studios are the practical way in.', 'Hongo / Ochanomizu', '2-4-16 Hongo, Bunkyo-ku, Tokyo', 'https://www.tokyoartsandspace.jp/', NULL, 'https://tokyoartsandspace.jp/en/exhibition/index', ARRAY['emerging','residency','open_call','open_studio','international']::TEXT[], 3, 'yes', 'Bilingual site; some talks interpreted', 'html_calendar', false, 'https://artscape.jp/article/79951/', '2026-10-21', 'Free. 7 Nov Mino Arata performance needs booking. Ftarri is nearby in Suidobashi: pair them in one evening.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('tyo-xyz', 'XYZ collective', 'XYZ collective', 'artist_run_space', 'tokyo', 'active', 1, ARRAY['visual_art']::TEXT[], 'XYZ collective is an artist-run space founded in 2011 by the video artist COBRA with fellow artists, first in a remodelled warehouse in Setagaya and, since 2016, in a basement in Sugamo. It combines studios for artists in their twenties and thirties with an alternative exhibition space, and it also hosts music events and fashion shows.

It has built a strong international network of artist-run spaces: it has shown at art fairs abroad, curated shows in Los Angeles and Brussels, organised exhibitions at VOU in Kyoto, and co-curated TOKAS''s 2020 exhibition on artist-run scenes in Tokyo, Detroit and Berlin. Its 2026 programme included Yui Usui''s ''Our bodies of cotton'' (8 Aug–13 Sep).

Open Thursday to Sunday 13:00–18:00 (Saturdays to 17:00), free. Opening receptions are the natural moment to meet the people behind it.', 'Sugamo', 'B02, 2-13-4 Sugamo, Toshima-ku, Tokyo 170-0002', 'https://xyzcollective.jp/', NULL, 'https://xyzcollective.jp/', ARRAY['artist_run','studios','international_network','exhibitions']::TEXT[], 5, 'yes', 'Free; small basement space', 'html_calendar', true, 'https://www.tokyoartbeat.com/en/events/-/Yui-Usui-Our-bodies-of-cotton/2-CA-7-F8-F1/2026-08-08', '2026-10-21', 'Tokyo''s clearest artist-run node and a bridge to Kyoto (VOU). Autumn show not yet confirmed; check TAB. Own site not opened directly.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('tyo-morishita', 'Morishita Studio (The Saison Foundation)', '森下スタジオ（セゾン文化財団）', 'residency', 'tokyo', 'active', 2, ARRAY['dance','theatre','performance']::TEXT[], 'Morishita Studio is the rehearsal and residency facility of the Saison Foundation, a grant-making body founded in 1987 to support contemporary Japanese theatre and dance. It opened in 1994 in a residential part of Koto ward, a five-minute walk from Morishita subway station, and has four studios with plywood floors, mirrors and barres, plus guest rooms for residents.

Grantees can rent the studios at reasonable rates for rehearsals, workshops and work-in-progress showings. The Saison Artist in Residence programme hosts visiting fellows (artists and arts managers researching Japan''s performing-arts scene) with accommodation covered, and an international projects programme gives studio time to cross-border collaborations with Japanese partners; the current cycle offers the studio until 28 Dec 2026 and from 4 Jan to 31 Mar 2027.

It is not a public venue. Its value to a visiting artist is as a target for residency and collaboration applications; contact the foundation through its website.', 'Morishita (Koto)', '3-5-6 Morishita, Koto-ku, Tokyo 135-0004', 'http://www.saison.or.jp', NULL, NULL, ARRAY['residency','rehearsal_studio','grants','international_collaboration']::TEXT[], 3, 'no', 'International programme open to applicants based outside Japan who already have a Japanese artistic partner', 'manual', true, 'https://culture360.asef.org/opportunities/japan-saison-foundation-theatre-and-dance-international-projects-2026-programme', '2026-10-21', 'Infrastructure row for the client''s collaboration plans, not for this trip. Foundation site not opened directly; confirm open calls there.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('tyo-bonobo', 'bonobo', 'bonobo（神宮前）', 'club', 'tokyo', 'active', 1, ARRAY['music']::TEXT[], 'bonobo is a small club in a renovated two-storey house in Jingumae, near Kitasando Station, open since 2003. The ground floor holds the dance floor; upstairs is a lounge with tatami seating and an open atrium, which gives nights a living-room feel.

Most nights are thrown by collectives and young DJs, from house and techno to experimental electronics and live sets. Recent examples: ''Michikusa'' (29 Jul 2026) with live acts on one floor and long DJ sets on the other, and the Brussels DJ Mika Oki at ''Save Point'' (29 May 2026). Doors are usually 22:00, often running to 05:00 or 06:00, with entry around ¥2,000–2,500 including one drink.

Events are listed on Resident Advisor; ages 18+ or 20+ depending on the night, so bring ID.', 'Jingumae / Kitasando', '2-23-4 Jingumae, Shibuya-ku, Tokyo 150-0001', NULL, 'https://www.instagram.com/jingumaebonobo/', NULL, ARRAY['club','collectives','house','techno','experimental_electronic','small_room']::TEXT[], 4, 'yes', '18+ or 20+ depending on night; photo ID', 'ra', true, 'https://ra.co/events/2482057', '2026-10-21', 'Low-key club for meeting the younger crowd. Instagram URL built from the handle on RA flyers; official site not opened.', false)
ON CONFLICT (source_id) DO UPDATE SET name=EXCLUDED.name, name_ja=EXCLUDED.name_ja, about=EXCLUDED.about, status=EXCLUDED.status, website_url=EXCLUDED.website_url, instagram_url=EXCLUDED.instagram_url, calendar_url=EXCLUDED.calendar_url, evidence_url=EXCLUDED.evidence_url, verified_at=EXCLUDED.verified_at, notes=EXCLUDED.notes;
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('tyo-dsoko', 'd-soko (d-倉庫)', 'd-倉庫', 'theatre_small', 'tokyo', 'closed', 3, ARRAY['dance','theatre','performance']::TEXT[], 'd-soko was a small theatre in a converted warehouse in Higashi-Nippori, about seven minutes from Nippori Station. It opened in December 2008 as part of the die pratze group of theatres, seated around 100 under a 4.7 m ceiling, and besides rentals it produced its own dance, butoh, theatre and performance festivals.

After a pandemic-era crowdfunding campaign to stay open, it closed at the end of December 2021; the final show was by the company Rakuen-O, and the building has since been demolished.

It is kept here only as a closed record, because older guides and artist CVs still mention it. Do not send anyone to this address.', 'Higashi-Nippori', '6-19-7 Higashi-Nippori, Arakawa-ku, Tokyo 116-0014', NULL, NULL, NULL, ARRAY['closed','butoh','festival_history']::TEXT[], 4, 'no', NULL, 'manual', false, 'https://shogekijo-network.jp/theaters/nippori_dsouko/', '2026-10-21', 'CLOSED end of December 2021; building demolished. Do not send anyone here.', false)
