UPDATE public.sources SET website_url='https://jazzartsengawa.org/', instagram_url='https://www.instagram.com/jazzartsengawa/', calendar_url='https://jazzartsengawa.org/timetable/', about='JAZZ ART SENGAWA is an artist-produced festival of improvised and genre-free music at Chofu City Sengawa Theater, run by an executive committee of artists. The 2026 edition runs 5-8 Nov 2026 at Sengawa Theater, POSTO and Sengawa Station Park, with a free outdoor stage (CLUB JAZZ Byobu) on 7-8 Nov that needs no ticket. Tickets and updates go through the festival site, Peatix, X and Instagram.', evidence_url='https://jazzartsengawa.org/', verified_at='2026-10-20' WHERE source_id='tyo-jazzartsengawa';
