UPDATE public.sources SET website_url='https://super-deluxe.com/', calendar_url='https://super-deluxe.com/events/', instagram_url='https://www.instagram.com/sdlx.jp/', verified_at='2026-10-20' WHERE source_id='tyo-superdeluxe';
UPDATE public.sources SET about='Maro Akaji''s butoh company (since 1972). "Alter Ego" (Akaji Maro x Eric-Maria Couturier) runs 29 Oct-1 Nov 2026 at Theatre Tram, with a post-show talk on 30 Oct. Ask about the Kochuten studio series, where company members direct small-scale works.' WHERE source_id='tyo-dairakudakan';
UPDATE public.sources SET about='Organiser collective running a yearly week of ambient and drone concerts, talks and workshops across small Tokyo rooms and DOMMUNE. The 2026 week was in May; Food For Ears vol.12 follows on 7 Nov 2026 at Black Bird Eatery.' WHERE source_id='tyo-miminoimi';
COMMIT;
